import React, { useState, useEffect } from "react";
import { useLocation } from "react-router-dom";
import './css/leaderboard.css'


const players = [
    { rank: 1, name: "Alex", score: 2560, accuracy: 96, quizzes: 24 },
    { rank: 2, name: "Sara", score: 2340, accuracy: 94, quizzes: 22 },
    { rank: 3, name: "Ahmed", score: 2210, accuracy: 92, quizzes: 21 },
    { rank: 4, name: "John", score: 2050, accuracy: 91, quizzes: 20 },
    { rank: 5, name: "You", score: 1980, accuracy: 89, quizzes: 19 },
    { rank: 6, name: "Maria", score: 1920, accuracy: 87, quizzes: 18 },
    { rank: 7, name: "David", score: 1850, accuracy: 85, quizzes: 17 },
    { rank: 8, name: "James", score: 1760, accuracy: 84, quizzes: 16 },
];

export function Leaderboard() {
    const [showDetails, setShowDetails] = useState(false);

    const topThree = players.slice(0, 3);
    const remainingPlayers = players.slice(3);
    const location = useLocation()
    // for the space background
    useEffect(() => {
        if (location.pathname !== "/leaderboard") return;
        const starsContainer = document.getElementById("stars");

        if (!starsContainer) return;
        starsContainer.innerHTML = "";

        for (let i = 0; i < 180; i++) {
            const star = document.createElement("div");

            const size =
                Math.random() > 0.96
                    ? "lg"
                    : Math.random() > 0.7
                        ? "md"
                        : "sm";

            star.className = `star ${size}`;

            star.style.left = Math.random() * 100 + "%";
            star.style.top = Math.random() * 100 + "%";

            star.style.animationDuration =
                2 + Math.random() * 6 + "s";

            star.style.animationDelay =
                Math.random() * 5 + "s";

            starsContainer.appendChild(star);
        }
    }, [location.pathname]);
    return (
        <div className="container py-5">
            <div id='stars'></div>
            {/* Header */}
            <div className="text-center mb-4">
                <h1 className=" text-white fw-bold">
                    🏆 Quiz Leaderboard Result
                </h1>
                <p className="text-white">
                    See how they rank against each other !
                </p>
            </div>

            {/* Tabs */}
            {/* <div className="d-flex justify-content-center mb-5">
                <div className="btn-group">
                    {["Today", "This Week", "All Time"].map((tab) => (
                        <button
                            key={tab}
                            className={`btn ${activeTab === tab
                                    ? "btn-primary"
                                    : "btn-outline-primary"
                                }`}
                            onClick={() => setActiveTab(tab)}
                        >
                            {tab}
                        </button>
                    ))}
                </div>
            </div> */}

            {/* Top 3 */}
            <div className="row justify-content-center align-items-end g-4 mb-5">
                {/* Second Place */}
                {/* Top 3 Leaderboard */}
                <div className="top-three-section">

                    {/* Show / Hide button */}
                    <div className="text-center mb-4">
                        <button
                            className="btn btn-outline-info display-btn fw-bold rounded-5 p-3"
                            onClick={() => setShowDetails(!showDetails)}
                        >
                            {showDetails ? "👁 Hide " : "✨ Show     Winners"}
                        </button>
                    </div>

                    <div className="row justify-content-center align-items-end g-4 mb-5">

                        {/* SECOND PLACE */}
                        <div className="col-10 col-sm-8 col-md-4 col-lg-3">
                            <div
                                className={`flip-card top-card silver-card ${showDetails ? "force-flipped" : ""
                                    }`}
                            >
                                <div className="flip-card-inner text-center w-100 h-100 position-relative">
                                    <div className="flip-card-front">
                                        <div className="rank-medal">
                                            🥈
                                        </div>
                                        <div className="rank-number text-white test">
                                            #2
                                        </div>

                                        <div className="rank-label">
                                            SECOND PLACE
                                        </div>
                                    </div>

                                    {/* BACK - Player details */}
                                    <div className="flip-card-back">
                                        <div className="rank-medal">
                                            🥈
                                        </div>

                                        <h3 className="player-name text-white fw-bolder fs-5 my-1">
                                            {topThree[1].name}
                                        </h3>
                                        <div className="player-score fw-bolder">
                                            {topThree[1].score.toLocaleString()}
                                        </div>

                                        <small>POINTS</small>


                                    </div>

                                </div>
                            </div>
                        </div>


                        {/* FIRST PLACE */}
                        <div className="col-10 col-sm-8 col-md-4 col-lg-3">
                            <div
                                className={`flip-card top-card gold-card ${showDetails ? "force-flipped" : ""
                                    }`}
                            >
                                <div className="flip-card-inner text-center w-100 h-100 position-relative">

                                    {/* FRONT */}
                                    <div className="flip-card-front">
                                        <div className="crown fs-2">
                                            👑
                                        </div>

                                        <div className="rank-medal">
                                            🥇
                                        </div>

                                        <div className="rank-number text-white test">
                                            #1
                                        </div>

                                        <div className="rank-label">
                                            CHAMPION
                                        </div>
                                    </div>

                                    {/* BACK */}
                                    <div className="flip-card-back">
                                        <div className="crown fs-2">
                                            👑
                                        </div>

                                        <div className="rank-medal">
                                            🥇
                                        </div>
                                        <h3 className="player-name text-white fw-bolder fs-5 my-1">
                                            {topThree[0].name}
                                        </h3>
                                        <div className="player-score fw-bolder gold-score">
                                            {topThree[0].score.toLocaleString()}
                                        </div>
                                        <small>POINTS</small>


                                    </div>

                                </div>
                            </div>
                        </div>


                        {/* THIRD PLACE */}
                        <div className="col-10 col-sm-8 col-md-4 col-lg-3">
                            <div
                                className={`flip-card top-card bronze-card ${showDetails ? "force-flipped" : ""
                                    }`}
                            >
                                <div className="flip-card-inner text-center w-100 h-100 position-relative">

                                    {/* FRONT */}
                                    <div className="flip-card-front">
                                        <div className="rank-medal">
                                            🥉
                                        </div>

                                        <div className="rank-number text-white">
                                            #3
                                        </div>

                                        <div className="rank-label">
                                            THIRD PLACE
                                        </div>
                                    </div>

                                    {/* BACK */}
                                    <div className="flip-card-back">
                                        <div className="rank-medal">
                                            🥉
                                        </div>
                                        <h3 className="player-name text-white fw-bolder fs-5 my-1">
                                            {topThree[2].name}
                                        </h3>
                                        <div className="player-score fw-bolder">
                                            {topThree[2].score.toLocaleString()}
                                        </div>
                                        <small>POINTS</small>

                                    </div>

                                </div>
                            </div>
                        </div>

                    </div>
                </div>
            </div>

            {/* Leaderboard Table */}
            <div className="card space-card border-0 shadow">
                <div className="card-body p-0">
                    <div className="table-responsive">
                        <table className="table table-hover align-middle mb-0 space-table">
                            <thead>
                                <tr>
                                    <th className="ps-4">Rank</th>
                                    <th>Player</th>
                                    <th>Score</th>
                                    <th>Accuracy</th>
                                    <th>Quizzes</th>
                                </tr>
                            </thead>

                            <tbody>
                                {remainingPlayers.map((player) => (
                                    <tr
                                        key={player.rank}
                                        className={
                                            player.name === "You"
                                                ? "space-current-player"
                                                : ""
                                        }
                                    >
                                        <td className="ps-4">
                                            <span className="badge rounded-pill space-rank">
                                                #{player.rank}
                                            </span>
                                        </td>

                                        <td>
                                            <div className="d-flex align-items-center">
                        
                                                {player.name}

                        
                                            </div>
                                        </td>

                                        <td>
                                            <span className="fw-bold space-score">
                                                {player.score.toLocaleString()}
                                            </span>
                                        </td>

                                        <td>
                                            <span className="badge bg-success">
                                                {player.accuracy}%
                                            </span> 
                                        </td>

                                        <td>{player.quizzes}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>  
        </div>
    );
}
